Http::preventStrayRequests();
if(($argv[1]??'')==='worker'){
 $start=microtime(true);$xml=app(InboundVoice::class)->receive(['AccountSid'=>'AC'.str_repeat('a',32),'CallSid'=>'CA'.str_pad($argv[2],32,'0',STR_PAD_LEFT),'From'=>'+5511999990000','To'=>'+16890000000']);echo json_encode(['ms'=>round((microtime(true)-$start)*1000,2),'dial'=>str_contains($xml,'<Dial'),'rejected'=>str_contains($xml,'<Reject')]);exit;
