Artisan::call('migrate:fresh',['--force'=>true]);$u=App\Models\User::factory()->create(['voice_workspace_id'=>1,'voice_role'=>'agent']);$campaign=DB::table('voice_campaigns')->insertGetId(['workspace_id'=>1,'name'=>'Load QA','settings'=>'{}']);$queue=DB::table('voice_live_queues')->insertGetId(['workspace_id'=>1,'campaign_id'=>$campaign,'name'=>'Load QA','agent_ids'=>json_encode([$u->id])]);DB::table('voice_inbound_routes')->insert(['workspace_id'=>1,'queue_id'=>$queue,'number'=>'+16890000000','enabled'=>true]);DB::table('voice_agent_presence')->insert(['user_id'=>$u->id,'workspace_id'=>1,'status'=>'available','last_seen_at'=>now()]);DB::table('voice_inbound_devices')->insert(['user_id'=>$u->id,'workspace_id'=>1,'session_id'=>(string)Illuminate\Support\Str::uuid(),'identity'=>'load_agent','ready'=>true,'last_seen_at'=>now()]);
$results=[];$parallel=4;$total=40;$wall=microtime(true);
for($batch=0;$batch<$total/$parallel;$batch++){$jobs=[];for($n=0;$n<$parallel;$n++){$pipes=[];$p=proc_open([PHP_BINARY,__FILE__,'worker',(string)($batch*$parallel+$n+1)],[1=>['pipe','w'],2=>['pipe','w']],$pipes);$jobs[]=[$p,$pipes];}foreach($jobs as [$p,$pipes]){$out=stream_get_contents($pipes[1]);$err=stream_get_contents($pipes[2]);fclose($pipes[1]);fclose($pipes[2]);if(proc_close($p)!==0)throw new RuntimeException($err);$v=json_decode($out,true,flags:JSON_THROW_ON_ERROR);$results[]=$v;}}
