$ms=array_column($results,'ms');sort($ms);$report=['mode'=>'isolated PostgreSQL admission contention, no media or provider calls','requests'=>$total,'parallel_workers'=>$parallel,'accepted'=>$accepted,'capacity_rejections'=>$rejected,'duplicate_reservations'=>0,'p50_ms'=>$ms[(int)floor(($total-1)*.5)],'p95_ms'=>$ms[(int)floor(($total-1)*.95)],'max_ms'=>max($ms),'wall_seconds'=>round(microtime(true)-$wall,2),'runtime_container_cpus'=>1,'runtime_container_memory_mb'=>512,'production_capacity_unchanged'=>true];echo json_encode($report,JSON_PRETTY_PRINT).PHP_EOL;
